SELECT id, user_id, total_cents, created_at
FROM orders;

-- Remove the old parent only after its dependent rows have been copied.
DROP TABLE orders;
DROP TABLE users;
ALTER TABLE users_new RENAME TO users;
ALTER TABLE orders_new RENAME TO orders;

COMMIT;
